syntax:
class Derived : public Base {
  using Base::Base; // Inheriting constructor
  // ... other members ...
};

code_example:
#include <iostream>
#include <chrono>
struct Base {
  int data[100000];
  Base(int x) { for (int i = 0; i < 100000; ++i) data[i] = x; }
};
struct Derived : public Base {
  using Base::Base;
  int extra; 
  Derived(int x, int y) : Base(x), extra(y) {}
};
int main() {
  auto start = std::chrono::high_resolution_clock::now();
  Derived d1(10, 20);
  auto end = std::chrono::high_resolution_clock::now();
  auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);
  std::cout << "Time taken by explicit constructor: " << duration.count() << " microseconds" << std::endl;
  start = std::chrono::high_resolution_clock::now();
  Derived d2(30,40); //Compiler might optimize this significantly
  end = std::chrono::high_resolution_clock::now();
  duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);
  std::cout << "Time taken by inheriting constructor: " << duration.count() << " microseconds" << std::endl;
  return 0;
}
